// Heures ouvrées : week-ends exclus, jours ouvrés comptés 24h
let MondayEpoch = datetime(1970-01-05);
let dayIdx = (t: datetime) { toint(datetime_diff('day', startofday(t), MondayEpoch)) };
let weekendDaysBefore = (n: int) { 2 * (n / 7) + max_of(0, min_of(2, n % 7 - 5)) };
let bizHours = (s: datetime, e: datetime) {
    let s2 = case(dayofweek(s) == 6d, startofday(s) + 2d, dayofweek(s) == 0d, startofday(s) + 1d, s);
    let e2 = case(dayofweek(e) == 6d, startofday(e), dayofweek(e) == 0d, startofday(e) - 1d, e);
    iff(e2 <= s2, 0.0, datetime_diff('second', e2, s2) / 3600.0 - 24.0 * (weekendDaysBefore(dayIdx(e2)) - weekendDaysBefore(dayIdx(s2))))
};
let lookback = 365d;
let closedCycles = __TABLE__
    | where TimeGenerated > ago(lookback) and c_eventType in ('merged', 'closed')
    | distinct c_repo, c_prNumber, c_cycleStartAt;
let openCycles = __TABLE__
    | where TimeGenerated > ago(lookback)
    | where c_eventType in ('created', 'reopened', 'review_started')
    | where '*' in ({Application}) or c_application in ({Application})
    | where '*' in ({Repo}) or c_repo in ({Repo})
    | summarize arg_max(TimeGenerated, *) by c_repo, c_prNumber, c_cycleStartAt
    | join kind=leftanti closedCycles on c_repo, c_prNumber, c_cycleStartAt;
let waiting = openCycles
    | where c_eventType != 'review_started'
    | extend H = bizHours(todatetime(c_cycleStartAt), now());
let inReview = openCycles
    | where c_eventType == 'review_started'
    | extend H = bizHours(todatetime(c_reviewStartedAt), now());
union
  (waiting | summarize Nb = count() | extend Indicateur = '1. À prendre en charge'),
  (waiting | where H <= 48 | summarize Nb = count() | extend Indicateur = '2. Dont < 48h ouvrées'),
  (waiting | where H > 48 | summarize Nb = count() | extend Indicateur = '3. Dont > 48h ouvrées'),
  (inReview | summarize Nb = count() | extend Indicateur = '4. En cours de revue'),
  (inReview | where H > 96 | summarize Nb = count() | extend Indicateur = '5. Dont revue > 96h ouvrées')
| project Indicateur, Nb
| sort by Indicateur asc

