| where TimeGenerated {TimeRange}
| where c_eventType in ('merged', 'closed')
| where '*' in ({Application}) or c_application in ({Application})
| where '*' in ({Repo}) or c_repo in ({Repo})
| extend PriseEnCharge_h = bizHours(todatetime(c_cycleStartAt), todatetime(c_reviewStartedAt)),
         Revue_h = bizHours(todatetime(c_reviewStartedAt), todatetime(c_closedAt))
| summarize
